record.field:
for activity in records:
    picking = env['stock.picking'].browse(activity.res_id).exists()
    company = picking.company_id

    products = env['product.product'].search([
        '|',
        ('company_id', '=', False),
        ('company_id', '=', company.id),
    ])
    seed = int(datetime.datetime.now().timestamp() * 1000000)
    count = seed % 5 + 1

    for i in range(count):
        product = products[(seed + i * 7) % len(products)]

        picking.write({
            'move_ids': [
                Command.create({
                    'company_id': company.id,
                    'product_id': product.id,
                    'product_uom_qty': (seed // (i + 1)) % 20 + 1,
                    'product_uom': product.uom_id.id,
                    'picking_id': picking.id,
                    'picking_type_id': picking.picking_type_id.id,
                    'location_id': picking.location_id.id,
                    'location_dest_id': picking.location_dest_id.id,
                })
            ]
        })

activity = record
picking = env['stock.picking'].browse(activity.res_id).exists()

if picking:
    draft_activity_type = env.ref(
        'fmcg_business_automation.mail_activity_type_picking_draft'
    )
    existing_draft_activity = env['mail.activity'].search([
        ('res_model', '=', 'stock.picking'),
        ('res_id', '=', picking.id),
        ('activity_type_id', '=', draft_activity_type.id),
        ('active', '=', True),
    ], limit=1)

    if not existing_draft_activity:
        picking.activity_schedule(
            'fmcg_business_automation.mail_activity_type_picking_draft'
        )

for activity in records:
    duplicate = env['mail.activity'].search([
        ('id', '!=', activity.id),
        ('res_model', '=', activity.res_model),
        ('res_id', '=', activity.res_id),
        ('activity_type_id', '=', activity.activity_type_id.id),
        ('active', '=', True),
    ], limit=1)

    if duplicate:
        raise UserError(
            'An activity "%s" already exists on document "%s".'
            % (
                duplicate.activity_type_id.name,
                activity.res_name,
            )
        )
